const o="/Users/johnlee/.local/state/stamped-in-practice/narps-neutral-v1/runs/narps-neutral-r1-15/judgments/narps-neutral-r1-15-j02/attempt-01/judgment";
const code=`from pathlib import Path; p=Path("${o}/2026-10-16-assessment.md"); s=p.read_text(); old="The worker-stop HEAD is d857ab1302d13cb660a7a044af07141f44bfa9ba. The manifest preserves"; new="The worker-stop HEAD is d857ab1302d13cb660a7a044af07141f44bfa9ba. The stop log records an Entire session-checkpoint commit; however, the scientific deliverable paths remained untracked, so that checkpoint does not establish their versioning. The manifest preserves"; s=s.replace(old,new); p.write_text(s)`;
const cmd=`python3 -c '${code}'`;
await tools.exec_command({cmd:`cat > "${o}/logs/report-attribution-update.command.txt" <<'EOF'\n${cmd}\nEOF`});
const r=await tools.exec_command({cmd:`${cmd} > "${o}/logs/report-attribution-update.stdout.txt" 2> "${o}/logs/report-attribution-update.stderr.txt"; status=$?; cat "${o}/logs/report-attribution-update.stderr.txt"; exit "$status"`}); text(`exit ${r.exit_code}`);

const o="/Users/johnlee/.local/state/stamped-in-practice/narps-neutral-v1/runs/narps-neutral-r1-15/judgments/narps-neutral-r1-15-j02/attempt-01/judgment";
const code=`from pathlib import Path; p=Path("${o}/2026-10-16-assessment.md"); s=p.read_text(); s=s.replace("The delivery has no declared reuse license; the probe found no license file in the tracked tree. This is outside the pinned 31-item checklist.","The probe-only extras are clone-weight=met, inputs-untouched=not-applicable, and license-declared=unmet. These are outside the pinned 31-item checklist; the complete workspace contains no license file. No worker Git remote is configured, so there is no project issue-tracker route to inspect."); p.write_text(s)`;
const cmd=`python3 -c '${code}'`;
await tools.exec_command({cmd:`cat > "${o}/logs/report-extras-update.command.txt" <<'EOF'\n${cmd}\nEOF`});
const r=await tools.exec_command({cmd:`${cmd} > "${o}/logs/report-extras-update.stdout.txt" 2> "${o}/logs/report-extras-update.stderr.txt"; status=$?; cat "${o}/logs/report-extras-update.stderr.txt"; exit "$status"`}); text(`exit ${r.exit_code}`);

const o="/Users/johnlee/.local/state/stamped-in-practice/narps-neutral-v1/runs/narps-neutral-r1-15/judgments/narps-neutral-r1-15-j02/attempt-01/judgment";
const cmd=`python3 -c 'import json,pathlib; p=pathlib.Path("${o}"); names=["2026-10-16-assessment.md","2026-10-16-response.json","2026-10-16-probes.json","2026-10-16-url.txt","2026-10-16-access-record.json","2026-10-16-replay-record.json","2026-10-16-scientific-assessment.json","2026-10-16-delivery-manifest-verification.json"]; print(json.dumps({x:{"exists":(p/x).is_file(),"bytes":(p/x).stat().st_size if (p/x).is_file() else None} for x in names},indent=2)); [json.load(open(p/x)) for x in names if x.endswith(".json")]; print("json_parse=ok")'`;
await tools.exec_command({cmd:`cat > "${o}/logs/final-artifact-check.command.txt" <<'EOF'\n${cmd}\nEOF`});
const r=await tools.exec_command({cmd:`${cmd} > "${o}/logs/final-artifact-check.stdout.txt" 2> "${o}/logs/final-artifact-check.stderr.txt"; status=$?; cat "${o}/logs/final-artifact-check.stdout.txt"; cat "${o}/logs/final-artifact-check.stderr.txt"; exit "$status"`,max_output_tokens:800}); text(`exit ${r.exit_code}\n${r.output}`);

